/// Lets `unchecked_param_type` / `unchecked_return_type` name the generated
/// types as `B.<Name>`, the narrowed TS types as `T.<Name>` and `R<X>` (every
/// array readonly), so the package's d.ts is typed without TS wrappers.
#[wasm_bindgen(typescript_custom_section)]
const BINDINGS_IMPORT: &str = r#"import type * as B from "../src/bindings.js";
import type * as T from "../src/ts-types.js";
import type { ReadonlyInput as R } from "../src/readonly-input.js";"#;

/// Converts a value to the JS shape `bindings.ts` declares for it. Every
/// export returns through here.
///
/// The default `serde_wasm_bindgen` serializer turns `None` into `undefined`
/// and maps into a JS `Map`, while the generated types say `null` and a plain
/// object; `json_compatible` produces those.
fn to_js<T: Serialize>(value: &T) -> Result<JsValue, serde_wasm_bindgen::Error> {
    value.serialize(&serde_wasm_bindgen::Serializer::json_compatible())
}

/// [`wf_core::core_info`] as a plain JS object (`CoreInfo` in `bindings.ts`).
///
/// # Errors
///
/// Fails only if the value cannot be converted to a JS value.
#[wasm_bindgen(js_name = coreInfo, unchecked_return_type = "B.CoreInfo")]
pub fn core_info() -> Result<JsValue, serde_wasm_bindgen::Error> {
    to_js(&wf_core::core_info())
}

/// Largest text, in UTF-16 code units, that `tokenize`, `indexTerms` and
/// `parseQuery` accept (16 Mi units, 32 MiB as UTF-16). Larger input is an error, never
/// truncated. The exports take a `JsString` and check it with `guarded_text` before
/// copying, so oversize text never grows linear memory; `check_text` stays for direct
/// callers. The core itself has no cap (phase-1-search.md, Limits).
pub const MAX_INDEX_TEXT_UTF16: usize = 1 << 24;

/// [`MAX_INDEX_TEXT_UTF16`] for JS, so the wrappers check the cap before the
/// text is copied into linear memory.
#[must_use]
#[wasm_bindgen(js_name = maxIndexTextUtf16)]
pub fn max_index_text_utf16() -> usize {
    MAX_INDEX_TEXT_UTF16
}

/// Fails when `text` is over [`MAX_INDEX_TEXT_UTF16`] UTF-16 units.
fn check_text(text: &str) -> Result<(), serde_wasm_bindgen::Error> {
    // Checked at compile time: a runtime `debug_assert!` on a const trips clippy's assertions_on_constants.
    const _: () = assert!(MAX_INDEX_TEXT_UTF16 > 0);
    // UTF-16 length never exceeds UTF-8 byte length, so short input skips the scan.
    if text.len() > MAX_INDEX_TEXT_UTF16 {
        let len = utf16_len(text);
        if len > MAX_INDEX_TEXT_UTF16 {
            return Err(serde_wasm_bindgen::Error::new(format!(
                "text is {len} UTF-16 units; MAX_INDEX_TEXT_UTF16 is {MAX_INDEX_TEXT_UTF16}"
            )));
        }
    }
    debug_assert!(utf16_len(text) <= MAX_INDEX_TEXT_UTF16);
    debug_assert!(text.len() <= MAX_INDEX_TEXT_UTF16 * 3);
    Ok(())
}

/// Copies `text` out of JS after checking it against [`MAX_INDEX_TEXT_UTF16`].
///
/// Exports take the text as a `JsString` and call this, so oversize text is
/// refused before it is copied into linear memory (which never shrinks).
pub(crate) fn guarded_text(text: &js_sys::JsString) -> Result<String, serde_wasm_bindgen::Error> {
    let len = text.length() as usize;
    if len > MAX_INDEX_TEXT_UTF16 {
        return Err(serde_wasm_bindgen::Error::new(format!(
            "text is {len} UTF-16 units; MAX_INDEX_TEXT_UTF16 is {MAX_INDEX_TEXT_UTF16}"
        )));
    }
    Ok(String::from(text))
}

/// Reads the JS options object and checks `text` against the cap.
fn index_input(
    text: &str,
    options: JsValue,
) -> Result<TokenizerOptions, serde_wasm_bindgen::Error> {
    check_text(text)?;
    debug_assert!(utf16_len(text) <= MAX_INDEX_TEXT_UTF16);
    debug_assert!(text.len() <= MAX_INDEX_TEXT_UTF16 * 3);
    serde_wasm_bindgen::from_value(options)
}

/// [`wf_core::search::tokenizer::tokenize`]: search terms of `text`, deduplicated.
///
/// # Errors
///
/// Fails if `text` exceeds `MAX_INDEX_TEXT_UTF16` UTF-16 units, or if
/// `options` is not a valid `TokenizerOptions` object.
#[wasm_bindgen(js_name = tokenize, unchecked_return_type = "string[]")]
pub fn tokenize(
    text: js_sys::JsString,
    #[wasm_bindgen(unchecked_param_type = "B.TokenizerOptions")] options: JsValue,
) -> Result<JsValue, serde_wasm_bindgen::Error> {
    let text = &guarded_text(&text)?;
    let options = index_input(text, options)?;
    debug_assert!(text.len() <= MAX_INDEX_TEXT_UTF16 * 3);
    let terms = core_tokenize(text, &options);
    debug_assert!(terms.iter().all(|t| t.len() <= text.len() * 3));
    to_js(&terms)
}

/// [`wf_core::search::tokenizer::index_terms`]: what MiniSearch indexes for `text`.
///
/// # Errors
///
/// Fails if `text` exceeds `MAX_INDEX_TEXT_UTF16` UTF-16 units, or if
/// `options` is not a valid `TokenizerOptions` object.
#[wasm_bindgen(js_name = indexTerms, unchecked_return_type = "string[]")]
pub fn index_terms(
    text: js_sys::JsString,
    #[wasm_bindgen(unchecked_param_type = "B.TokenizerOptions")] options: JsValue,
) -> Result<JsValue, serde_wasm_bindgen::Error> {
    let text = &guarded_text(&text)?;
    let options = index_input(text, options)?;
    debug_assert!(text.len() <= MAX_INDEX_TEXT_UTF16 * 3);
    let terms = core_index_terms(text, &options);
    debug_assert!(terms.iter().all(|t| t.len() <= text.len() * 3));
    to_js(&terms)
}

/// [`wf_core::search::query::parse_query`]: the query split into terms, phrases,
/// exclusions and filters.
///
/// # Errors
///
/// Fails if `query` exceeds `MAX_INDEX_TEXT_UTF16` UTF-16 units.
#[wasm_bindgen(js_name = parseQuery, unchecked_return_type = "B.ParsedQuery")]
pub fn parse_query(query: js_sys::JsString) -> Result<JsValue, serde_wasm_bindgen::Error> {
    let query = &guarded_text(&query)?;
    let parsed = wf_core::search::query::parse_query(query);
    debug_assert!(parsed.text.len() <= query.len() * 3);
    debug_assert!(parsed.modified_within_days.is_none_or(|d| d >= 1));
    to_js(&parsed)
}

/// UTF-16 units `terms` cost against [`MAX_INDEX_TEXT_UTF16`]: each term counts
/// its length + 1, so many empty terms are capped too.
fn excerpt_terms_cost(terms: &[String]) -> usize {
    terms
        .iter()
        .map(|t| utf16_len(t).saturating_add(1))
        .fold(0, usize::saturating_add)
}

/// Reads the JS terms and checks their cost against [`MAX_INDEX_TEXT_UTF16`].
fn excerpt_terms(terms: JsValue) -> Result<Vec<String>, serde_wasm_bindgen::Error> {
    let terms: Vec<String> = serde_wasm_bindgen::from_value(terms)?;
    let total = excerpt_terms_cost(&terms);
    if total > MAX_INDEX_TEXT_UTF16 {
        return Err(serde_wasm_bindgen::Error::new(format!(
            "terms need {total} UTF-16 units (length + 1 each); MAX_INDEX_TEXT_UTF16 is {MAX_INDEX_TEXT_UTF16}"
        )));
    }
    debug_assert!(excerpt_terms_cost(&terms) <= MAX_INDEX_TEXT_UTF16);
    debug_assert!(terms.len() <= MAX_INDEX_TEXT_UTF16);
    debug_assert!(terms.iter().all(|t| t.len() <= MAX_INDEX_TEXT_UTF16 * 3));
    Ok(terms)
}

/// [`wf_core::search::excerpt::build_excerpt`]: a snippet of `body` around the
/// densest cluster of `terms`, as `{ text, highlights }` where `text` is UTF-16
/// code units (the TS wrapper turns them into a string, lone surrogates kept).
/// `max_chars` defaults to 240 and `single_line` to true.
///
/// # Errors
///
/// Fails if `body` exceeds `MAX_INDEX_TEXT_UTF16` UTF-16 units, or `terms`
/// do (each counting its length + 1), or if `terms` is not an array of strings.
#[wasm_bindgen(js_name = buildExcerpt)]
pub fn build_excerpt(
    body: js_sys::JsString,
    terms: JsValue,
    max_chars: Option<u32>,
    single_line: Option<bool>,
) -> Result<JsValue, serde_wasm_bindgen::Error> {
    let body = &guarded_text(&body)?;
    let terms = excerpt_terms(terms)?;
    let options = ExcerptOptions {
        max_chars: max_chars.and_then(|n| usize::try_from(n).ok()),
        single_line: single_line.unwrap_or(true),
    };
    let excerpt = wf_core::search::excerpt::build_excerpt(body, &terms, options);
    debug_assert!(
        excerpt
            .highlights
            .iter()
            .all(|h| h.start < h.end && h.end <= excerpt.text.len())
    );
    debug_assert!(excerpt.text.len() <= utf16_len(body) + 2);
    to_js(&excerpt)
}

/// Most ids all ranked lists together may carry into `fuseRankings` (about
/// 1 Mi). More is an error; the TS wrapper checks before the ids cross into WASM.
pub const MAX_FUSION_IDS: usize = 1 << 20;

/// [`MAX_FUSION_IDS`] for JS.
#[must_use]
#[wasm_bindgen(js_name = maxFusionIds)]
pub fn max_fusion_ids() -> usize {
    MAX_FUSION_IDS
}

/// Reads the JS lists and checks their total size and each weight.
fn fusion_input(lists: JsValue) -> Result<Vec<RankedList>, serde_wasm_bindgen::Error> {
    let lists: Vec<RankedList> = serde_wasm_bindgen::from_value(lists)?;
    let total: usize = lists.iter().map(|l| l.ids.len()).sum();
    if total > MAX_FUSION_IDS {
        return Err(serde_wasm_bindgen::Error::new(format!(
            "lists have {total} ids in total; MAX_FUSION_IDS is {MAX_FUSION_IDS}"
        )));
    }
    for (index, list) in lists.iter().enumerate() {
        if !list.weight.is_finite() || list.weight < 0.0 {
            return Err(serde_wasm_bindgen::Error::new(format!(
                "list {index} weight {} must be finite and >= 0",
                list.weight
            )));
        }
    }
    debug_assert!(lists.iter().map(|l| l.ids.len()).sum::<usize>() <= MAX_FUSION_IDS);
    debug_assert!(
        lists
            .iter()
            .all(|l| l.weight.is_finite() && l.weight >= 0.0)
    );
    Ok(lists)
}

/// [`wf_core::search::fusion::fuse_rankings`]: distinct ids, best fused rank first.
/// `k` defaults to [`RRF_K`]; `limit` of `None` or 0 means no limit.
///
/// # Errors
///
/// Fails if a list is malformed, the lists have more than `MAX_FUSION_IDS` ids
/// in total, or a weight is not finite and >= 0.
#[wasm_bindgen(js_name = fuseRankings)]
pub fn fuse_rankings(
    lists: JsValue,
    k: Option<u32>,
    limit: Option<u32>,
) -> Result<JsValue, serde_wasm_bindgen::Error> {
    let lists = fusion_input(lists)?;
    let limit = limit
        .and_then(|n| usize::try_from(n).ok())
        .and_then(NonZeroUsize::new);
    let fused = wf_core::search::fusion::fuse_rankings(&lists, k.unwrap_or(RRF_K), limit);
    debug_assert!(fused.len() <= lists.iter().map(|l| l.ids.len()).sum::<usize>());
    debug_assert!(limit.is_none_or(|n| fused.len() <= n.get()));
    to_js(&fused)
}

/// [`wf_core::papers::paper_ref::parse_paper_ref`]: `value` as a `PaperRef`
/// (`PaperRef` in `bindings.ts`) of the given `kind`.
///
/// # Errors
///
/// Fails if `value` exceeds `MAX_INDEX_TEXT_UTF16` UTF-16 units, or if `kind`
/// is not a valid `PaperRefKind`.
#[wasm_bindgen(js_name = parsePaperRef, unchecked_return_type = "B.PaperRef")]
pub fn parse_paper_ref(
    #[wasm_bindgen(unchecked_param_type = "B.PaperRefKind")] kind: JsValue,
    value: js_sys::JsString,
) -> Result<JsValue, serde_wasm_bindgen::Error> {
    let value = &guarded_text(&value)?;
    let kind: PaperRefKind = serde_wasm_bindgen::from_value(kind)?;
    to_js(&wf_core::papers::paper_ref::parse_paper_ref(kind, value))
}

